```json
{
  "summary": "UIKlines",
  "description": "The request is similar to klines having the same parameters and response.\n\nuiKlines return modified kline data, optimized for presentation of candlestick charts.\n\nWeight(IP): 2",
  "tags": [
    "Market"
  ],
  "parameters": [
    {
      "$ref": "#/components/parameters/symbol"
    },
    {
      "name": "interval",
      "in": "query",
      "required": true,
      "description": "kline intervals",
      "schema": {
        "type": "string",
        "enum": [
          "1s",
          "1m",
          "3m",
          "5m",
          "15m",
          "30m",
          "1h",
          "2h",
          "4h",
          "6h",
          "8h",
          "12h",
          "1d",
          "3d",
          "1w",
          "1M"
        ],
        "example": "\"1m\""
      }
    },
    {
      "$ref": "#/components/parameters/startTime"
    },
    {
      "$ref": "#/components/parameters/endTime"
    },
    {
      "name": "timeZone",
      "in": "query",
      "required": false,
      "description": "Default: 0 (UTC)",
      "schema": {
        "type": "string"
      }
    },
    {
      "$ref": "#/components/parameters/limit"
    }
  ],
  "responses": {
    "200": {
      "description": "UIKline data",
      "content": {
        "application/json": {
          "schema": {
            "type": "array",
            "items": {
              "type": "array",
              "items": {
                "oneOf": [
                  {
                    "type": "integer",
                    "format": "int64"
                  },
                  {
                    "type": "string"
                  }
                ],
                "minItems": 12,
                "maxItems": 12
              },
              "example": [
                1499040000000,
                "0.01634790",
                "0.80000000",
                "0.01575800",
                "0.01577100",
                "148976.11427815",
                1499644799999,
                "2434.19055334",
                308,
                "1756.87402397",
                "28.46694368",
                "0"
              ]
            }
          }
        }
      }
    },
    "400": {
      "description": "Bad Request",
      "content": {
        "application/json": {
          "schema": {
            "$ref": "#/components/schemas/error"
          }
        }
      }
    }
  }
}
```

